css:
@import url("https://fonts.googleapis.com/css2?family=Anybody:wdth,wght@75..150,400..900&family=Fragment+Mono&display=swap");
:root{--bp:#0B3D91;--bp2:#0A3179;--bp3:#1A52B0;--yl:#FFD23F;--pb:#E8EEFA;--ink:#0E1A33;--gr:#4C5873;--ln:#D3DDF0;--h:"Anybody",system-ui,sans-serif;--m:"Fragment Mono",ui-monospace,monospace}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--h);font-size:17px;line-height:1.65;color:var(--ink);background:#fff;font-stretch:100%}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:800;margin:0;line-height:1;font-stretch:125%}
.wrap{max-width:1180px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--yl);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--yl);outline-offset:2px}
.hero{background:var(--bp);color:#fff;background-image:linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px);background-size:32px 32px}
.nav{display:flex;justify-content:space-between;align-items:center;height:80px;position:relative}.logo{font-weight:900;font-stretch:150%;font-size:24px;text-decoration:none;display:flex;gap:10px;align-items:center}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:var(--yl)}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;font-size:20px;cursor:pointer}
.hg{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:center;padding:40px 0 90px}.hg>div{min-width:0}
.hero h1{font-size:clamp(46px,6.6vw,92px);text-transform:uppercase}.hero h1 span{color:var(--yl);display:block}
.hero p{font-size:19px;color:#C8D6F2;max-width:30em;margin:22px 0 28px}
.btn{display:inline-block;background:var(--yl);color:var(--ink);text-decoration:none;font:700 17px var(--h);padding:15px 26px;border:0;cursor:pointer}.btn.o{background:transparent;color:#fff;box-shadow:inset 0 0 0 2px #fff}.btn.b{background:var(--bp);color:#fff}
.row{display:flex;flex-wrap:wrap;gap:12px}
.ed{background:#0A2A63;border:2px solid #2A5DB8;font-family:var(--m);font-size:15px;box-shadow:12px 12px 0 var(--yl)}
.ed .bar{display:flex;gap:6px;padding:10px 12px;border-bottom:2px solid #2A5DB8;align-items:center}.ed .bar i{width:11px;height:11px;border-radius:50%;background:#2A5DB8}.ed .bar span{margin-left:10px;color:#9CB4E4;font-size:13px}
.ed pre{margin:0;padding:18px 20px;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.7;min-height:230px;color:#E8EEFA}.ed .k{color:var(--yl)}.ed .s{color:#9FE2BF}.ed .c{color:#7F97C8}
.cur{display:inline-block;width:9px;height:18px;background:var(--yl);vertical-align:-3px;animation:bl 1s steps(1) infinite}@keyframes bl{50%{opacity:0}}
.ed .eout{border-top:2px solid #2A5DB8;padding:12px 20px;color:#9FE2BF;min-height:46px}
.dates{background:var(--yl)}.dates .wrap{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px 30px;padding-top:16px;padding-bottom:16px;font-weight:600}.dates b{font-stretch:125%}
section{padding:86px 0}.sh{max-width:680px;margin-bottom:30px}.sh h2{font-size:clamp(38px,5vw,64px);text-transform:uppercase;color:var(--bp)}.sh p{color:var(--gr);margin:12px 0 0;font-size:18px}
.tabs{display:flex;flex-wrap:wrap;border:2px solid var(--bp);margin-bottom:26px}.tabs button{flex:1 1 200px;font:700 17px var(--h);font-stretch:112%;background:#fff;border:0;border-right:2px solid var(--bp);padding:16px;cursor:pointer;color:var(--bp);text-align:left}.tabs button:last-child{border-right:0}
.tabs button small{display:block;font-weight:400;font-family:var(--m);font-size:13px;color:var(--gr)}.tabs button[aria-pressed=true]{background:var(--bp);color:#fff}.tabs button[aria-pressed=true] small{color:#C8D6F2}
.tg{display:grid;grid-template-columns:.8fr 1.2fr;gap:36px;align-items:start}.tg>div{min-width:0}
.ti h3{font-size:34px;text-transform:uppercase;color:var(--bp)}.ti p{color:var(--gr)}.ti dl{display:grid;grid-template-columns:auto 1fr;gap:8px 18px;margin:18px 0 22px}.ti dt{font-family:var(--m);font-size:14px;color:var(--gr)}.ti dd{margin:0;font-weight:700}
.ti img{width:100%;aspect-ratio:3/2;object-fit:cover;margin-top:10px}
.wk{border:2px solid var(--ln);margin-bottom:-2px}.wk h4{margin:0}.wk button{width:100%;display:grid;grid-template-columns:118px 1fr 24px;gap:12px;align-items:center;background:#fff;border:0;padding:14px 18px;cursor:pointer;text-align:left;font:700 18px var(--h);color:var(--ink)}
.wk .n{font-family:var(--m);font-weight:400;font-size:14px;color:var(--bp3)}.wk .pl{font-family:var(--m);font-size:20px;transition:transform .2s}.wk button[aria-expanded=true]{background:var(--pb)}.wk button[aria-expanded=true] .pl{transform:rotate(45deg)}
.wk .bd{padding:4px 18px 16px 148px;color:var(--gr);font-size:16px;background:var(--pb)}.wk .bd code{font-family:var(--m);background:#fff;padding:1px 6px;font-size:14px;color:var(--bp)}
.out{background:var(--pb)}.og{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}.og>div{min-width:0}
.big{display:grid;grid-template-columns:1fr 1fr;gap:16px}.big div{background:#fff;padding:22px;border-left:6px solid var(--yl)}.big div{min-width:0}.big b{display:block;font-size:clamp(34px,7vw,52px);font-weight:900;font-stretch:125%;color:var(--bp);line-height:1}.big span{color:var(--gr);font-size:15px}
.chart{background:#fff;padding:24px}.chart h3{font-size:22px;margin-bottom:6px;font-stretch:112%}.chart p{margin:0 0 16px;color:var(--gr);font-size:15px}
.cb{display:grid;grid-template-columns:130px 1fr 60px;gap:10px;align-items:center;margin:10px 0;font-size:15px}.cb .tr{height:22px;background:var(--pb)}.cb .tr i{display:block;height:100%;background:var(--bp);width:0;transition:width .8s}.cb b{font-family:var(--m);font-weight:400;text-align:right}
.apply .wrap{max-width:820px}
.prog{display:flex;gap:6px;margin-bottom:20px;list-style:none;padding:0}.prog li{flex:1;border-top:6px solid var(--ln);padding-top:8px;font-family:var(--m);font-size:13px;color:var(--gr)}.prog li.on{border-color:var(--bp);color:var(--bp)}
form{border:2px solid var(--bp);padding:30px;box-shadow:10px 10px 0 var(--yl)}.step[hidden]{display:none}.fr{display:grid;grid-template-columns:1fr 1fr;gap:14px}.fr>div{min-width:0}
label,.lb{display:block;font-weight:700;font-size:15px;margin-bottom:6px}input,select,textarea{width:100%;font:16px var(--h);padding:12px;border:2px solid var(--ln);margin-bottom:14px;color:var(--ink);background:#fff}
.rad{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:14px}.rad label{position:relative;cursor:pointer;margin:0}.rad input{position:absolute;opacity:0;width:1px;height:1px;left:0;top:0}.rad span{display:block;border:2px solid var(--ln);padding:12px;font-weight:600;font-size:15px}.rad input:checked+span{border-color:var(--bp);background:var(--pb)}.rad input:focus-visible+span{outline:3px solid var(--yl)}
.nb{display:flex;justify-content:space-between;gap:10px;margin-top:6px}.err{color:#B3261E;font-weight:600;min-height:24px;margin:0}
.done{visibility:hidden;background:var(--pb);padding:16px;font-weight:600;margin-top:14px}.done.on{visibility:visible}
footer{background:var(--bp2);color:#C8D6F2;padding:30px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.hg,.tg,.og{grid-template-columns:1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:80px;left:0;right:0;background:var(--bp);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.tabs button{border-right:0;border-bottom:2px solid var(--bp)}.wk button{grid-template-columns:1fr 20px}.wk .n{grid-column:1/-1}.wk .bd{padding-left:18px}.big{grid-template-columns:1fr 1fr}.cb{grid-template-columns:96px 1fr 50px}.fr,.rad{grid-template-columns:1fr}.ed{box-shadow:6px 6px 0 var(--yl)}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}.cur{animation:none}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const src=[['c','// Week 1, day 1. You wrote this.'],['n',''],['k','const '],['p','name = '],['s','"Priya"'],['p',';'],['n',''],['k','function '],['p','greet(who) {'],['n',''],['p','  '],['k','return '],['s','`Hello, ${who}!`'],['p',';'],['n',''],['p','}'],['n',''],['p','console.log(greet(name));']];
const esc=t=>t.replace(/&/g,'&amp;').replace(/</g,'&lt;');let html='';
const full=src.map(([c,t])=>c==='n'?'\n':c==='p'?esc(t):`<span class="${c}">${esc(t)}</span>`).join('');
if(matchMedia('(prefers-reduced-motion: reduce)').matches){$('code').innerHTML=full;$('out').textContent='> Hello, Priya!'}else{let i=0,j=0;const tick=()=>{if(i>=src.length){$('code').innerHTML=html+'<span class="cur"></span>';$('out').textContent='> Hello, Priya!';return}const [c,t]=src[i];
if(c==='n'){html+='\n';i++}else if(j<t.length){j++;const part=esc(t.slice(0,j));$('code').innerHTML=html+(c==='p'?part:`<span class="${c}">${part}</span>`)+'<span class="cur"></span>';if(j===t.length){html+=c==='p'?esc(t):`<span class="${c}">${esc(t)}</span>`;i++;j=0}}setTimeout(tick,14)};tick()}
const T=[["Web development","16 weeks, full time","Build websites and web apps from the ground up, then learn the tools real teams use.","Mon to Fri, 9am to 5pm","$15,900",[["HTML and CSS","Page structure, layout with <code>grid</code> and <code>flexbox</code>, accessibility basics."],["JavaScript basics","Variables, functions, loops and the DOM. Build a quiz game."],["JavaScript in depth","Arrays, objects, <code>fetch</code> and working with APIs."],["Git and teamwork","Branches, pull requests and code review in pairs."],["React","Components, state and routing. Build a recipe app."],["Back end with Node","Servers, databases and REST APIs with <code>Express</code>."],["Testing and deploy","Automated tests, hosting and your first live app."],["Final project","4 weeks in a team of 4, building something for a real client."]]],
["Data analytics","12 weeks, full time","Turn messy spreadsheets into clear answers with SQL, Python and dashboards.","Mon to Fri, 9am to 5pm","$12,900",[["Spreadsheets properly","Formulas, pivot tables and cleaning data."],["SQL","<code>SELECT</code>, joins and grouping on real company data."],["Python for data","<code>pandas</code>, notebooks and simple charts."],["Statistics you'll use","Averages, spread, A/B tests and when to trust a result."],["Dashboards","Build a live dashboard for a business question."],["Final project","3 weeks analysing a data set from a hiring partner."]]],
["UX design","12 weeks, part time","Learn to research, sketch, prototype and test products people find easy to use.","Tue and Thu evenings, plus Saturdays","$9,800",[["What UX is","The design process and how teams work together."],["User research","Interviews, surveys and turning notes into insights."],["Sketching and wireframes","Fast ideas on paper, then clean wireframes."],["Prototypes","Clickable prototypes and design systems."],["Testing","Run usability tests and fix what you find."],["Portfolio project","A full case study you can show employers."]]]];
let tr=0;function tabs(){$('tabs').innerHTML=T.map((t,i)=>`<button type="button" aria-pressed="${i===tr}" data-i="${i}">${t[0]}<small>${t[1]}</small></button>`).join('')}
function track(){const t=T[tr];$('tn').textContent=t[0];$('td').textContent=t[2];$('tl').textContent=t[1];$('ts').textContent=t[3];$('tp').textContent=t[4];
const per=t[0]==='Web development'?2:2;$('wks').innerHTML=t[5].map((w,i)=>{const a=i*per+1,b=i===t[5].length-1?(t[1].startsWith('16')?16:12):a+per-1;return`<div class="wk"><h4><button type="button" aria-expanded="${i===0}" aria-controls="w${i}"><span class="n">Week ${a===b?a:a+' to '+b}</span><span>${w[0]}</span><span class="pl" aria-hidden="true">+</span></button></h4><div class="bd" id="w${i}" ${i===0?'':'hidden'}>${w[1]}</div></div>`}).join('');$('xa').setAttribute('aria-pressed','false');$('xa').textContent='Open all'}
$('tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;tr=+b.dataset.i;tabs();track()};
$('wks').onclick=e=>{const b=e.target.closest('button');if(!b)return;const o=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',o);$(b.getAttribute('aria-controls')).hidden=!o};
$('xa').onclick=()=>{const o=$('xa').getAttribute('aria-pressed')!=='true';document.querySelectorAll('.wk button').forEach(b=>{b.setAttribute('aria-expanded',o);$(b.getAttribute('aria-controls')).hidden=!o});$('xa').setAttribute('aria-pressed',o);$('xa').textContent=o?'Close all':'Open all'};tabs();track();
const B=[["Front-end developer",34],["Full-stack developer",22],["Data analyst",18],["UX designer",11],["QA and support",9],["Other tech roles",6]];
$('bars').innerHTML=B.map(b=>`<div class="cb"><span>${b[0]}</span><span class="tr"><i data-w="${b[1]/34*100}"></i></span><b>${b[1]}%</b></div>`).join('');
requestAnimationFrame(()=>setTimeout(()=>document.querySelectorAll('.cb i').forEach(i=>i.style.width=i.dataset.w+'%'),60));
let st=0;const steps=[...document.querySelectorAll('.step')];
function show(){steps.forEach((s,i)=>s.hidden=i!==st);[...$('prog').children].forEach((l,i)=>l.classList.toggle('on',i<=st));$('bk').hidden=st===0;$('nx').textContent=st===2?'Send application':'Next step';$('err').textContent=''}
$('bk').onclick=()=>{st--;show()};
$('nx').onclick=()=>{const bad=[...steps[st].querySelectorAll('[required]')].find(f=>!f.value.trim()||(f.type==='email'&&!f.value.includes('@')));if(bad){$('err').textContent='Please fill in: '+document.querySelector(`label[for=${bad.id}]`).textContent;bad.focus();return}
if(st<2){st++;show();steps[st].querySelector('input,select,textarea').focus()}else{$('done').textContent=`Thanks ${$('an').value}! Your application for ${document.querySelector('input[name=track]:checked').value} is in. We'll email ${$('ae').value} within 2 working days to book your chat.`;$('done').classList.add('on');$('nx').disabled=true}};
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
